import{_ as i,l as r,o as e,c as o,v as t,p as s,x as l,d as p,i as h,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LELELE","description":"","frontmatter":{"title":"LELELE","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lelele-triple.md","filePath":"litho/lelele-triple.md","lastUpdated":1789023840000}'),d={name:"litho/lelele-triple.md"};function c(L,a,A,_,m,u){const E=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="lelele" tabindex="-1">LELELE <a class="header-anchor" href="#lelele" aria-label="Permalink to &quot;LELELE&quot;">​</a></h1><div class="epigraph"><p>冲突图出现奇数环，两次染色不够：第三次光刻–刻蚀把那一环拆开，套刻从两张版变成三张版同时活在同一节距里。</p><footer>—— 据多重图形（DPT）对三重曝光 LELELE 与 3-着色的通称整理</footer></div><p><a href="/litho/lele-color-decomposition">上一课</a>把 LELE 写成冲突图可 2-染色，并点名：奇数环必须改布局、stitch，或升级到三次。缺口是把第三次展开成工艺与预算，而不是再画一遍二分图。自对准从<a href="/litho/sadp-saqp">下一课</a>另起，本课不改写成 spacer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2-着色失败的典型是奇数冲突环：三根线两两都近于同色间距，任何两色都会让其中一对同色。LELELE（litho-etch × 3）把多边形分到三张掩模，每张回到单次可印间距，三次刻蚀把线拼回目标密度。理论上节距可按三份拆；实际上三次套刻 \\(\\delta_{12},\\delta_{13},\\delta_{23}\\) 与三次 CD 全部进入相邻 space。</p><p>缺口因此是 3-色与三套 overlay，不是再解释 \\(k_1\\) 地板。把「三次所以密度 ×3」写成无条件，等于假设冲突图总是 3-可着色且三次套刻为零。stitch 在 3-色里仍然存在：同一根线跨色，接头处有两次或三次边缘对位。</p><h3 id="三色不是两次再加一次免费" tabindex="-1">三色不是两次再加一次免费 <a class="header-anchor" href="#三色不是两次再加一次免费" aria-label="Permalink to &quot;三色不是两次再加一次免费&quot;">​</a></h3><p>每次 litho-etch 都有胶、刻蚀偏置、套刻。第三次往往是为了那一小撮奇数环或最密的二维结，却让整层的机时与掩模张数跳一档。设计规则若能靠改布局消掉奇环，通常比上 LELELE 便宜。本课承认三重是 2-色的升级，不是默认目标。</p><p><span class="marginnote">有的层用「两次线 + 一次切」或 SADP，并不叫 LELELE。名字专指三次线层曝光–刻蚀着色。切层三重是另一张预算，后课 cut 再写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解：冲突图 3-着色（NP-难的工程近似：启发式、拆段、局部 stitch）。同色间距仍受单次光学限制；异色间距受两两 overlay 与 CD 限制，三对异色各有一条规则。签核要看最坏的那一对 space，不能只报平均节距。</p><p>工艺：三次涂胶曝光刻蚀，中间图形要扛住后续刻蚀的微负载——先写下的色会被后两次等离子体再修一刀，CD 偏置按色序分裂。计量：三套套刻标记、三套 ADI/AEI，pitch walking 式的「邻边一宽一窄」在 LELELE 上来自 overlay 而不是 spacer。</p><h3 id="与-lele-的增量" tabindex="-1">与 LELE 的增量 <a class="header-anchor" href="#与-lele-的增量" aria-label="Permalink to &quot;与 LELE 的增量&quot;">​</a></h3><p>上一课的 2-色工具仍在：冲突边、同色/异色间距、stitch。增量是色数、套刻对数、色序刻蚀负载。若 2-色只在少数单元失败，优先局部改设计或 stitch；全芯片 3-色是最后杠杆。</p>',14)),(e(),s(n,null,{default:l(()=>[h(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ODD%5B%22%E5%A5%87%E6%95%B0%E5%86%B2%E7%AA%81%E7%8E%AF%22%5D%20--%3E%20C3%5B%223-%E7%9D%80%E8%89%B2%22%5D%0A%20%20C3%20--%3E%20M1%5B%22%E6%8E%A9%E6%A8%A1%E8%89%B2%201%22%5D%0A%20%20C3%20--%3E%20M2%5B%22%E6%8E%A9%E6%A8%A1%E8%89%B2%202%22%5D%0A%20%20C3%20--%3E%20M3%5B%22%E6%8E%A9%E6%A8%A1%E8%89%B2%203%22%5D%0A%20%20M1%20--%3E%20LE%5B%22%E4%B8%89%E6%AC%A1%20litho-etch%22%5D%0A%20%20M2%20--%3E%20LE%0A%20%20M3%20--%3E%20LE%0A%20%20LE%20--%3E%20OV%5B%22%E4%B8%89%E5%AF%B9%E5%A5%97%E5%88%BB%20%2B%20%E8%89%B2%E5%BA%8F%E5%81%8F%E7%BD%AE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次曝光只印稀疏子集，空中像回到可印 \\(k_1\\)。最终节距由三次图形的并集定义，相邻边若来自不同色，它们的间距误差是 \\(\\delta\\) 与两边 CD 误差之和。三次独立 \\(\\delta\\) 不会抵消，统计上 space 的方差比 LELE 更差，除非套刻控制按对数收紧。色序：第一色的硬掩模吃两次后续刻蚀，线宽系统偏与后两色不同，OPC 必须分色建模。</p><p>二维拐角与 T 结是奇环的高发区。分解器在这里切段，stitch 把电学上的一根线变成工艺上的两段接头，可靠性预算另计。DPT 文献把这写成可着色性与制造的交界，而不是光学魔术。</p><p><span class="marginnote">不要用商品节点的「三重图形」新闻稿反推某层一定是 LELELE。它可能是 SAQP、切三重、或孔的 LELELE。要看是不是三次线层着色。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编三次套刻各几个纳米，不写某代金属层张数。SADP/SAQP 用薄膜劈节距，套刻结构不同，下一课才讲；不要把 LELELE 的 \\(\\delta\\) 语言搬到 spacer 的 core/gap 上。EUV 单次若已印下，三重 DUV 的动机消失——那是后课层策略，本课只给 2-色失败时的 DUV 出口。</p><p>掩模是三块 6 寸版，物流与 PEC 各做三次，成本按张数加，不是按节距线性加。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LELELE 是冲突图 3-着色后的三次光刻–刻蚀，用来拆 2-色奇环或更密二维。</li><li>三对套刻与色序刻蚀负载进入相邻 space；不是密度免费 ×3。</li><li>优先改布局消奇环；全芯片三重是升级不是默认。</li><li>分色 OPC 与分色计量；stitch 仍在。</li><li>出处：双重/三重图形 DPT 对 3-着色与 LELELE 的通称。</li></ul>',9))])}const P=i(d,[["render",c]]);export{B as __pageData,P as default};
